<?php session_start();require 'php/conexion.php';if(!isset($_SESSION['pedido'])){exit('No existe pedido activo');}$id=(int)$_SESSION['pedido'];$s=$conn->prepare('SELECT id,nombre,telefono,direccion,metodo_pago,estado FROM pedidos WHERE id=? LIMIT 1');$s->bind_param('i',$id);$s->execute();$pedido=$s->get_result()->fetch_assoc();if(!$pedido)exit('Pedido no encontrado');$s=$conn->prepare('SELECT p.nombre,c.cantidad,c.costototal FROM carrito c INNER JOIN productos p ON c.productos_id=p.id WHERE c.pedidos_id=?');$s->bind_param('i',$id);$s->execute();$r=$s->get_result();$total=0;?><!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Recibo - Dragon Ice</title><link rel="stylesheet" href="css/dragonice.css">
</head><body><h1>DRAGON ICE</h1><h2>Recibo de Pedido</h2><p>Número: <?=$pedido['id']?></p><p>Cliente: <?=htmlspecialchars($pedido['nombre'])?></p><p>Teléfono: <?=htmlspecialchars($pedido['telefono'])?></p><p>Dirección: <?=htmlspecialchars($pedido['direccion'])?></p><p>Método de pago: <?=htmlspecialchars($pedido['metodo_pago'])?></p><p>Estado: <?=htmlspecialchars($pedido['estado'])?></p><hr><h3>Productos</h3><?php while($p=$r->fetch_assoc()){$total+=(float)$p['costototal'];echo '<p>'.htmlspecialchars($p['nombre']).'<br>Cantidad: '.$p['cantidad'].'<br>Subtotal: Bs '.number_format($p['costototal'],2).'</p>';} ?><h2>Total: Bs <?=number_format($total,2)?></h2><h3>Esperando aprobación del vendedor</h3><button onclick="window.print()">🖨 Imprimir</button><button id="volverProductos">Volver a Productos</button><script>document.getElementById('volverProductos').addEventListener('click',()=>fetch('php/nueva_compra.php').then(r=>r.json()).then(d=>{if(d.ok)location.href='index.php'}));</script></body></html>
